INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Lasttests immer notwendig für kleine Systeme?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend bei geringer Last"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Test wähle ich, um die maximale Belastung zu prüfen?', 3, '[{"text": "Lasttest", "correct": true, "because": "Simuliert hohe Nutzerzahlen"}, {"text": "Antwortzeitentest", "correct": false, "because": "Fokussiert Reaktionszeit"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Performancetest effektiv?', 5, '[{"text": "Realistische Szenarien", "correct": true, "because": "Spiegelt Nutzung wider"}, {"text": "Messbare Ergebnisse", "correct": true, "because": "Daten für Optimierung"}, {"text": "Geringer Aufwand", "correct": false, "because": "Gründlichkeit zählt"}, {"text": "Einfache Tools", "correct": false, "because": "Komplexität oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lasttests simulieren Spitzenlast. b) Antwortzeiten sind bei kleinen Systemen egal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Antwortzeiten immer relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Performancetest für einen Webserver?', 4, '[{"text": "Antwortzeiten", "correct": false, "because": "Kern der Nutzererfahrung"}, {"text": "Lastgrenzen", "correct": false, "because": "Definiert Kapazität"}, {"text": "Farbschema der UI", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Lasttests die Antwortzeiten ignorieren?', 2, '[{"text": "Nein", "correct": true, "because": "Antwortzeiten Teil des Tests"}, {"text": "Ja", "correct": false, "because": "Wichtiger Messwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel priorisiere ich bei einem Antwortzeitentest?', 3, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Nutzererlebnis optimieren"}, {"text": "Maximale Last", "correct": false, "because": "Lasttest-Ziel"}, {"text": "Einfache Ausführung", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Lasttest?', 5, '[{"text": "Kapazitätsplanung", "correct": true, "because": "Grenzen erkennen"}, {"text": "Stabilitätsprüfung", "correct": true, "because": "Verhalten unter Druck"}, {"text": "Geringer Ressourcenbedarf", "correct": false, "because": "Tests benötigen Ressourcen"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Dauert oft länger"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Antwortzeiten sind bei Lasttests irrelevant. b) Lasttests simulieren Nutzer. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, Antwortzeiten wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Performancetest?', 4, '[{"text": "Testskripte", "correct": false, "because": "Simulieren Last"}, {"text": "Messwerkzeuge", "correct": false, "because": "Erfassen Ergebnisse"}, {"text": "Optisches Design", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Antwortzeiten nur bei kleinen Lasten wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei hoher Last relevant"}, {"text": "Ja", "correct": false, "because": "Immer entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für einen Lasttest entscheidend?', 4, '[{"text": "Nutzeranzahl", "correct": true, "because": "Simuliert Belastung"}, {"text": "Systemressourcen", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Minimale Dauer", "correct": false, ".Concurrent": false, "because": "Ausführlichkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Performancetests nur für große Systeme sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme profitieren"}, {"text": "Ja", "correct": false, "because": "Nicht größenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Antwortzeitentest für eine Web-App?', 3, '[{"text": "Nutzererfahrung", "correct": true, "because": "Schnelligkeit entscheidend"}, {"text": "Maximale Last", "correct": false, "because": "Lasttest-Fokus"}, {"text": "Einfache Tools", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lasttests prüfen Systemgrenzen. b) Antwortzeiten sind bei Servern unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Antwortzeiten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Lasttest?', 5, '[{"text": "Hoher Ressourcenbedarf", "correct": true, "because": "Simuliert viele Nutzer"}, {"text": "Komplexität", "correct": true, "because": "Erfordert Planung"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Dauert oft länger"}, {"text": "Geringer Nutzen", "correct": false, "because": "Liefert wertvolle Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Performancetest für eine Datenbank unwichtig?', 3, '[{"text": "Antwortzeiten", "correct": false, "because": "Kritisch für Abfragen"}, {"text": "Lastverhalten", "correct": false, "because": "Definiert Grenzen"}, {"text": "UI-Design", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Lasttests nur für Produktionssysteme?', 3, '[{"text": "Nein", "correct": true, "because": "Auch in Entwicklung nützlich"}, {"text": "Ja", "correct": false, "because": "Frühzeitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Antwortzeiten bei hohen Lasten gemessen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Teil von Lasttests"}, {"text": "Nein", "correct": false, "because": "Wichtiger Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Test wähle ich für eine E-Commerce-Plattform?', 4, '[{"text": "Lasttest", "correct": true, "because": "Simuliert Spitzenzeiten"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu ungenau"}, {"text": "Einzelnutzertest", "correct": false, "because": "Ignoriert Last"}]');
